/** Inline SVG markup for an icon (512x512 viewBox, currentColor). */
export function icon(name: string, cls = ''): string {
  return `<svg class="ico ${cls}" viewBox="0 0 512 512" aria-hidden="true">${(ICONS[name] ?? '').replace(/fill="#fff"/g, 'fill="currentColor"')}</svg>`;
}
